package org.apache.accumulo.test.ample.metadata;

import java.util.Map;

import org.apache.accumulo.core.conf.SiteConfiguration;
import org.apache.accumulo.core.metadata.schema.Ample;
import org.apache.accumulo.core.metadata.schema.Ample.DataLevel;
import org.apache.accumulo.server.ServerContext;

import com.google.common.base.Suppliers;

/**
 * A test-only {@link ServerContext} that returns an {@link Ample} backed by {@link TestAmple} using
 * a {@link FlakyInterceptor}. This causes conditional mutations against the metadata and user tables
 * to have ambiguous ({@link org.apache.accumulo.core.client.ConditionalWriter.Status#UNKNOWN})
 * outcomes, which exercises code that must tolerate not knowing whether a conditional mutation
 * succeeded.
 */
public class FlakyAmpleServerContext extends ServerContext {

  // The tables map intentionally mirrors the default (non-ROOT) data level to table mapping so that
  // the flaky ample operates against the real metadata tables. The ROOT level is excluded because
  // TestAmple does not intercept it.
  private final com.google.common.base.Supplier<Ample> ample = Suppliers.memoize(
      () -> TestAmple.create(this, Map.of(DataLevel.METADATA, DataLevel.METADATA.metaTable(),
          DataLevel.USER, DataLevel.USER.metaTable()), FlakyInterceptor::new));

  public FlakyAmpleServerContext(SiteConfiguration siteConfig) {
    super(siteConfig);
  }

  @Override
  public Ample getAmple() {
    return ample.get();
  }
}
